'use strict';

/* PXL-URG-0071A — coalesce CRM/Invoice N+1 Supabase reads.
 * This transport shim does not change Invoice/CRM business rules. It only groups
 * concurrent relation lookups generated by the existing Invoice V1 repair flow
 * and skips crm_invoices PATCH calls when cached persisted values are identical.
 */

const INSTALL_KEY = Symbol.for('pxl.urg.0071a.crm.batch.fetch');

function inputUrl(input) {
  if (typeof input === 'string') return input;
  if (input instanceof URL) return input.href;
  if (input && typeof input.url === 'string') return input.url;
  return String(input || '');
}

function methodOf(input, init) {
  return String(init?.method || input?.method || 'GET').toUpperCase();
}

function jsonResponse(value, source) {
  const headers = new Headers(source?.headers || undefined);
  headers.set('content-type', 'application/json');
  return new Response(JSON.stringify(value), {
    status: source?.status || 200,
    statusText: source?.statusText || 'OK',
    headers
  });
}

function textResponse(text, source) {
  return new Response(text, {
    status: source?.status || 500,
    statusText: source?.statusText || '',
    headers: source?.headers || undefined
  });
}

function parseEq(value) {
  value = String(value || '');
  return value.startsWith('eq.') ? value.slice(3) : null;
}

function parseIn(value) {
  value = String(value || '');
  if (!value.startsWith('in.(') || !value.endsWith(')')) return null;
  return value.slice(4, -1).split(',').map(x => x.trim()).filter(Boolean);
}

function projectRows(rows, select) {
  if (!select || select === '*') return rows;
  const fields = select.split(',').map(x => x.trim()).filter(x => /^[A-Za-z0-9_]+$/.test(x));
  if (!fields.length) return rows;
  return rows.map(row => {
    const out = {};
    for (const field of fields) if (Object.prototype.hasOwnProperty.call(row, field)) out[field] = row[field];
    return out;
  });
}

function stable(value) {
  if (Array.isArray(value)) return value.map(stable);
  if (value && typeof value === 'object') {
    return Object.keys(value).sort().reduce((out, key) => {
      out[key] = stable(value[key]);
      return out;
    }, {});
  }
  return value;
}

function sameValue(a, b) {
  return JSON.stringify(stable(a)) === JSON.stringify(stable(b));
}

function patchIsUnchanged(existing, payload) {
  if (!existing || !payload || typeof payload !== 'object' || Array.isArray(payload)) return false;
  return Object.keys(payload)
    .filter(key => key !== 'updated_at')
    .every(key => sameValue(existing[key], payload[key]));
}

function makeQueue(windowMs, flush) {
  let pending = [];
  let timer = null;
  return item => new Promise((resolve, reject) => {
    pending.push({ ...item, resolve, reject });
    if (timer) return;
    timer = setTimeout(async () => {
      const batch = pending;
      pending = [];
      timer = null;
      try { await flush(batch); }
      catch (error) { for (const entry of batch) entry.reject(error); }
    }, windowMs);
  });
}

function createBatchingFetch(baseFetch, options = {}) {
  if (typeof baseFetch !== 'function') throw new TypeError('baseFetch wajib berupa function');
  const windowMs = Math.max(0, Number(options.windowMs ?? 12));
  const crmInvoiceCache = new Map();
  const metrics = { batchedRequests: 0, savedReads: 0, skippedPatches: 0 };
  const queues = new Map();

  function queueFor(key, flush) {
    if (!queues.has(key)) queues.set(key, makeQueue(windowMs, flush));
    return queues.get(key);
  }

  async function flushEqBatch(batch, config) {
    const first = batch[0];
    const ids = [...new Set(batch.map(x => x.value).filter(Boolean))];
    const url = new URL(first.url.href);
    url.searchParams.delete(config.param);
    url.searchParams.delete('limit');
    url.searchParams.set(config.param, `in.(${ids.join(',')})`);
    if (config.batchSelect) url.searchParams.set('select', config.batchSelect);
    const response = await baseFetch(url.href, first.init);
    const raw = await response.text();
    if (!response.ok) {
      for (const entry of batch) entry.resolve(textResponse(raw, response));
      return;
    }
    let rows = [];
    try { rows = raw ? JSON.parse(raw) : []; } catch (_) { rows = []; }
    if (!Array.isArray(rows)) rows = [];
    if (config.cacheRows) config.cacheRows(rows);
    metrics.batchedRequests += 1;
    metrics.savedReads += Math.max(0, batch.length - 1);
    for (const entry of batch) {
      const filtered = rows.filter(row => String(row[config.rowField] ?? '') === String(entry.value));
      entry.resolve(jsonResponse(projectRows(filtered, entry.select), response));
    }
  }

  async function flushInBatch(batch, config) {
    const first = batch[0];
    const union = [...new Set(batch.flatMap(x => x.values || []))];
    const url = new URL(first.url.href);
    url.searchParams.set(config.param, `in.(${union.join(',')})`);
    if (config.batchSelect) url.searchParams.set('select', config.batchSelect);
    const response = await baseFetch(url.href, first.init);
    const raw = await response.text();
    if (!response.ok) {
      for (const entry of batch) entry.resolve(textResponse(raw, response));
      return;
    }
    let rows = [];
    try { rows = raw ? JSON.parse(raw) : []; } catch (_) { rows = []; }
    if (!Array.isArray(rows)) rows = [];
    metrics.batchedRequests += 1;
    metrics.savedReads += Math.max(0, batch.length - 1);
    for (const entry of batch) {
      const wanted = new Set((entry.values || []).map(String));
      const filtered = rows.filter(row => wanted.has(String(row[config.rowField] ?? '')));
      entry.resolve(jsonResponse(projectRows(filtered, entry.select), response));
    }
  }

  async function wrappedFetch(input, init = {}) {
    const method = methodOf(input, init);
    const href = inputUrl(input);
    let url;
    try { url = new URL(href); } catch (_) { return baseFetch(input, init); }
    if (!url.pathname.startsWith('/rest/v1/')) return baseFetch(input, init);

    const table = url.pathname.slice('/rest/v1/'.length);
    const select = url.searchParams.get('select') || '';

    if (method === 'GET' && table === 'invoice_items') {
      const invoiceId = parseEq(url.searchParams.get('invoice_id'));
      if (invoiceId) {
        const key = `invoice_items|${select}|${url.searchParams.get('order') || ''}`;
        const enqueue = queueFor(key, batch => flushEqBatch(batch, {
          param: 'invoice_id', rowField: 'invoice_id', batchSelect: select || '*'
        }));
        return enqueue({ url, init, value: invoiceId, select });
      }
    }

    if (method === 'GET' && table === 'invoice_work_orders' && select === 'ticket_id') {
      const invoiceId = parseEq(url.searchParams.get('invoice_id'));
      if (invoiceId) {
        const enqueue = queueFor('invoice_work_orders|ticket_id', batch => flushEqBatch(batch, {
          param: 'invoice_id', rowField: 'invoice_id', batchSelect: 'invoice_id,ticket_id'
        }));
        return enqueue({ url, init, value: invoiceId, select });
      }
    }

    if (method === 'GET' && table === 'crm_customers' && select === 'id,name,status') {
      const id = parseEq(url.searchParams.get('id'));
      if (id) {
        const enqueue = queueFor('crm_customers|id', batch => flushEqBatch(batch, {
          param: 'id', rowField: 'id', batchSelect: 'id,name,status'
        }));
        return enqueue({ url, init, value: id, select });
      }
    }

    if (method === 'GET' && table === 'crm_invoices' && select === 'id') {
      const number = parseEq(url.searchParams.get('invoice_number'));
      if (number) {
        const enqueue = queueFor('crm_invoices|invoice_number', batch => flushEqBatch(batch, {
          param: 'invoice_number', rowField: 'invoice_number', batchSelect: '*',
          cacheRows: rows => { for (const row of rows) if (row?.id) crmInvoiceCache.set(String(row.id), row); }
        }));
        return enqueue({ url, init, value: number, select });
      }
    }

    if (method === 'GET' && table === 'sales_orders') {
      const id = parseEq(url.searchParams.get('id'));
      if (id && select === 'id,so_number,customer_id,customer_name') {
        const enqueue = queueFor('sales_orders|crm-sync', batch => flushEqBatch(batch, {
          param: 'id', rowField: 'id', batchSelect: select
        }));
        return enqueue({ url, init, value: id, select });
      }
    }

    if (method === 'GET' && table === 'tickets') {
      const ids = parseIn(url.searchParams.get('id'));
      const syncSelect = 'id,wo_number,project_name,status,sales_order_id,so_number,crm_customer_id,customer_name,customer_phone,technician,created_by';
      if (ids && select === syncSelect) {
        const enqueue = queueFor('tickets|crm-sync', batch => flushInBatch(batch, {
          param: 'id', rowField: 'id', batchSelect: syncSelect
        }));
        return enqueue({ url, init, values: ids, select });
      }
    }

    if (method === 'PATCH' && table === 'crm_invoices') {
      const id = parseEq(url.searchParams.get('id'));
      const cached = id ? crmInvoiceCache.get(String(id)) : null;
      let payload = null;
      try { payload = typeof init.body === 'string' ? JSON.parse(init.body) : init.body; } catch (_) { }
      if (cached && patchIsUnchanged(cached, payload)) {
        metrics.skippedPatches += 1;
        return jsonResponse([cached]);
      }
      const response = await baseFetch(input, init);
      if (!id || !response.ok) return response;
      const raw = await response.text();
      let rows = [];
      try { rows = raw ? JSON.parse(raw) : []; } catch (_) { }
      if (Array.isArray(rows) && rows[0]) crmInvoiceCache.set(String(id), rows[0]);
      return jsonResponse(rows, response);
    }

    return baseFetch(input, init);
  }

  wrappedFetch.PXL_URG_0071A = { revision: 'PXL-URG-0071A', metrics, crmInvoiceCache };
  return wrappedFetch;
}

function install() {
  if (global[INSTALL_KEY]) return global[INSTALL_KEY];
  const baseFetch = global.fetch;
  if (typeof baseFetch !== 'function') return null;
  const wrapped = createBatchingFetch(baseFetch);
  global.fetch = wrapped;
  global[INSTALL_KEY] = wrapped.PXL_URG_0071A;
  return global[INSTALL_KEY];
}

module.exports = { createBatchingFetch, install, patchIsUnchanged };

// db.js requires this module before db-core, so every Supabase adapter captures
// the same coalescing transport in Node/Vercel without route-level changes.
install();
